#!/usr/bin/env python3
"""Derive `flashnext_mtp8.hip` (workstream FN50) from `flashnext_moe.hip` (FN6, generated by
tools/gen_fn6_grouped.py): the MIXED-precision MTP expert table's two grouped GEMMs.

Qwen's first-party fp8 MTP experts are the ROUTED experts only; the MTP shared expert is bf16 in
every checkpoint. With `--fn-mtp-experts fp8` one xptr table holds both kinds -- a routed expert's
entry is `[e4m3 preshuffled weight, fp32 block scales]`, the shared expert's `[bf16 weight, 0]` --
and each GEMM runs as TWO launches over the same route tiles:

  fn_moe_a8w8_bs128_mx_g{1,0}   FN6's W8A8 body; a tile whose scale pointer is 0 (bf16) exits
  fn_moe_bgemm_sk_m16_mx_g{1,0} FN6's bf16 split-K body; a tile whose scale pointer is NOT 0 exits

Every other line is the shipped body's (one inserted line each, asserted anchors), so a computed
tile is byte-for-byte the shipped symbol's tile (the card gate: tools/capture/fn6/fn6_gate.py
section `mtp8`). The shipped `flashnext_moe` code object is NOT rebuilt: this is its own object.

    python3 tools/gen_fn50_mtp8.py           # (re)write
    python3 tools/gen_fn50_mtp8.py --check   # the committed file == its derivation
"""
import os
import sys

HIP = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "crates", "saber-kernels", "hip")
SRC = os.path.join(HIP, "flashnext_moe.hip")
OUT = os.path.join(HIP, "flashnext_mtp8.hip")

HEADER = """// GENERATED by tools/gen_fn50_mtp8.py from flashnext_moe.hip -- do not edit by hand.
//
// FN50: the MTP experts' MIXED table (Qwen's first-party fp8 routed experts + the bf16 shared
// expert). Each grouped GEMM is two launches over the same route tiles; the tile's scale pointer
// `xptr[2e + 1]` says which launch owns it (0 = bf16, the shared expert):
//   fn_moe_a8w8_bs128_mx_g{1,0}     FN6's W8A8 body, bf16 tiles exit
//   fn_moe_bgemm_sk_m16_mx_g{1,0}   FN6's bf16 split-K body, fp8 tiles exit
// One inserted line per body; a computed tile is the shipped symbol's bytes.
"""


def sub(text, old, new, n=1):
    k = text.count(old)
    if k != n:
        sys.exit(f"gen_fn50_mtp8: anchor {old!r} found {k}x (want {n})")
    return text.replace(old, new)


def derive():
    src = open(SRC).read()
    body = src[src.index("#include <hip/hip_runtime.h>"):]
    w_line = "  const __bf16 *__restrict__ w = (const __bf16 *)(uintptr_t)xptr[2 * (size_t)texp];\n"
    body = sub(body, w_line,
               w_line + "  if (xptr[2 * (size_t)texp + 1] != 0) return;   // FN50: an fp8 tile (the a8w8 mx launch's)\n")
    s_line = ("  const float *__restrict__ Ws = (const float *)(uintptr_t)xptr[2 * (size_t)texp + 1];\n")
    body = sub(body, s_line,
               s_line + "  if (Ws == nullptr) return;   // FN50: a bf16 tile (the shared expert; the bf16 mx launch's)\n")
    body = sub(body, "void fn_moe_bgemm_sk_m16_g", "void fn_moe_bgemm_sk_m16_mx_g", 2)
    body = sub(body, "void fn_moe_a8w8_bs128_g", "void fn_moe_a8w8_bs128_mx_g", 2)
    return HEADER + body


def main():
    want = derive()
    if "--check" in sys.argv:
        have = open(OUT).read() if os.path.exists(OUT) else ""
        if have != want:
            sys.exit("flashnext_mtp8.hip != its derivation (re-run tools/gen_fn50_mtp8.py)")
        print("flashnext_mtp8.hip matches its derivation")
        return
    with open(OUT, "w") as f:
        f.write(want)
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
